📖 Referência da API
📋 Visão Geral
Esta documentação fornece uma referência completa da API do Knowledge, incluindo interfaces TypeScript, configurações, métodos públicos e exemplos de uso.
🔧 Configuração Principal
DocForgeConfig
Interface principal de configuração do sistema.
interface DocForgeConfig {
    // Diretórios
    inputDir: string
    outputDir: string
    templatesDir?: string
    themesDir?: string
    // Informações do site
    site: SiteConfig
    // Tema e layout
    theme: string
    layout?: string
    // Navegação
    navigation: NavigationConfig
    // Funcionalidades
    features: FeatureConfig
    // Processamento Markdown
    markdown: MarkdownConfig
    // Servidor de desenvolvimento
    dev: DevConfig
}
SiteConfig
Configurações básicas do site.
interface SiteConfig {
    title: string
    description: string
    baseUrl: string
    author: string
    // Opcionais
    keywords?: string[]
    language?: string
    favicon?: string
    logo?: string
    // SEO e Social Media
    ogImage?: string
    ogType?: string
    twitterCard?: &amp;#39;summary&amp;#39; | &amp;#39;summary_large_image&amp;#39;
    twitterSite?: string
    // Analytics
    googleAnalytics?: string
    gtag?: string
    plausible?: string
    // Metadados customizados
    meta?: Record&amp;lt;string, string&amp;gt;
}
Exemplo:
site: {
    title: &amp;#39;Minha Documentação&amp;#39;,
    description: &amp;#39;Documentação técnica completa do projeto&amp;#39;,
    baseUrl: &amp;#39;/&amp;#39;,
    author: &amp;#39;Equipe de Desenvolvimento&amp;#39;,
    keywords: [&amp;#39;documentação&amp;#39;, &amp;#39;api&amp;#39;, &amp;#39;guias&amp;#39;],
    language: &amp;#39;pt-BR&amp;#39;,
    favicon: &amp;#39;/assets/favicon.ico&amp;#39;,
    ogImage: &amp;#39;/assets/og-image.png&amp;#39;,
    googleAnalytics: &amp;#39;GA_MEASUREMENT_ID&amp;#39;
}
NavigationConfig
Configuração da navegação do site.
interface NavigationConfig {
    auto: boolean
    items?: NavigationItem[]
    maxDepth?: number
    showHome?: boolean
    homeTitle?: string
}
interface NavigationItem {
    title: string
    url?: string
    icon?: string
    external?: boolean
    children?: NavigationItem[]
    order?: number
    hidden?: boolean
}
Navegação Automática:
navigation: {
    auto: true,
    maxDepth: 3,
    showHome: true,
    homeTitle: &amp;#39;Início&amp;#39;
}
Navegação Manual:
navigation: {
    auto: false,
    items: [
        {
            title: &amp;#39;Início&amp;#39;,
            url: &amp;#39;/&amp;#39;,
            icon: &amp;#39;home&amp;#39;
        },
        {
            title: &amp;#39;Guias&amp;#39;,
            children: [
                { title: &amp;#39;Instalação&amp;#39;, url: &amp;#39;/guides/installation.html&amp;#39; },
                { title: &amp;#39;Configuração&amp;#39;, url: &amp;#39;/guides/configuration.html&amp;#39; }
            ]
        },
        {
            title: &amp;#39;GitHub&amp;#39;,
            url: &amp;#39;https://github.com/riligar/knowledge&amp;#39;,
            external: true,
            icon: &amp;#39;github&amp;#39;
        }
    ]
}
FeatureConfig
Configuração das funcionalidades do sistema.
interface FeatureConfig {
    search?: boolean | SearchConfig
    syntaxHighlight?: boolean | SyntaxHighlightConfig
    darkMode?: boolean | DarkModeConfig
    tableOfContents?: boolean | TableOfContentsConfig
    breadcrumbs?: boolean | BreadcrumbsConfig
    editOnGithub?: string | EditOnGithubConfig
    comments?: boolean | CommentsConfig
    analytics?: boolean | AnalyticsConfig
}
SearchConfig
interface SearchConfig {
    enabled: boolean
    placeholder?: string
    noResultsText?: string
    maxResults?: number
    minQueryLength?: number
    indexFields?: {
        title?: { boost: number }
        excerpt?: { boost: number }
        content?: { boost: number }
        tags?: { boost: number }
    }
    stopWords?: string[]
    stemming?: boolean
}
Exemplo:
search: {
    enabled: true,
    placeholder: &amp;#39;Buscar na documentação...&amp;#39;,
    noResultsText: &amp;#39;Nenhum resultado encontrado&amp;#39;,
    maxResults: 10,
    minQueryLength: 2,
    indexFields: {
        title: { boost: 10 },
        excerpt: { boost: 5 },
        content: { boost: 1 },
        tags: { boost: 8 }
    }
}
SyntaxHighlightConfig
interface SyntaxHighlightConfig {
    enabled: boolean
    theme?: &amp;#39;github&amp;#39; | &amp;#39;monokai&amp;#39; | &amp;#39;dracula&amp;#39; | &amp;#39;tomorrow&amp;#39; | &amp;#39;vs2015&amp;#39;
    showLineNumbers?: boolean
    copyButton?: boolean
    languages?: string[]
    tabSize?: number
}
Exemplo:
syntaxHighlight: {
    enabled: true,
    theme: &amp;#39;github&amp;#39;,
    showLineNumbers: true,
    copyButton: true,
    languages: [&amp;#39;typescript&amp;#39;, &amp;#39;javascript&amp;#39;, &amp;#39;bash&amp;#39;, &amp;#39;json&amp;#39;, &amp;#39;yaml&amp;#39;],
    tabSize: 2
}
DarkModeConfig
interface DarkModeConfig {
    enabled: boolean
    defaultTheme?: &amp;#39;light&amp;#39; | &amp;#39;dark&amp;#39; | &amp;#39;auto&amp;#39;
    storageKey?: string
    toggleButton?: boolean
    systemPreference?: boolean
}
TableOfContentsConfig
interface TableOfContentsConfig {
    enabled: boolean
    levels?: number[]
    position?: &amp;#39;left&amp;#39; | &amp;#39;right&amp;#39; | &amp;#39;inline&amp;#39;
    title?: string
    minItems?: number
    maxItems?: number
}
BreadcrumbsConfig
interface BreadcrumbsConfig {
    enabled: boolean
    separator?: string
    showHome?: boolean
    homeText?: string
    maxItems?: number
}
EditOnGithubConfig
interface EditOnGithubConfig {
    enabled: boolean
    baseUrl: string
    branch?: string
    text?: string
    icon?: boolean
}
MarkdownConfig
Configuração do processamento de Markdown.
interface MarkdownConfig {
    // Configurações básicas
    breaks?: boolean
    linkify?: boolean
    typographer?: boolean
    html?: boolean
    // Extensões
    extensions?: {
        tables?: boolean
        strikethrough?: boolean
        tasklists?: boolean
        footnotes?: boolean
        math?: boolean
        mermaid?: boolean
        emoji?: boolean
        containers?: boolean
        deflist?: boolean
        abbr?: boolean
    }
    // Plugins customizados
    plugins?: string[] | MarkdownPlugin[]
    // Configurações de renderização
    renderer?: {
        heading?: (text: string, level: number) =&amp;gt; string
        link?: (href: string, title: string, text: string) =&amp;gt; string
        image?: (href: string, title: string, text: string) =&amp;gt; string
        code?: (code: string, language: string) =&amp;gt; string
    }
}
interface MarkdownPlugin {
    name: string
    plugin: any
    options?: any
}
Exemplo:
markdown: {
    breaks: true,
    linkify: true,
    typographer: true,
    html: false,
    extensions: {
        tables: true,
        strikethrough: true,
        tasklists: true,
        footnotes: true,
        math: true,
        mermaid: true,
        emoji: true
    },
    plugins: [
        {
            name: &amp;#39;markdown-it-container&amp;#39;,
            plugin: require(&amp;#39;markdown-it-container&amp;#39;),
            options: {
                name: &amp;#39;warning&amp;#39;,
                openTag: &amp;#39;&amp;lt;div class=&amp;quot;warning&amp;quot;&amp;gt;&amp;#39;,
                closeTag: &amp;#39;&amp;lt;/div&amp;gt;&amp;#39;
            }
        }
    ]
}
DevConfig
Configuração do servidor de desenvolvimento.
interface DevConfig {
    port: number
    host: string
    livereload?: boolean
    open?: boolean
    https?: boolean | {
        key: string
        cert: string
    }
    proxy?: Record&amp;lt;string, string&amp;gt;
    middleware?: DevMiddleware[]
}
interface DevMiddleware {
    path: string
    handler: (req: Request, res: Response, next: Function) =&amp;gt; void
}
🏗️ Classes Principais
DocumentationGenerator
Classe principal responsável pela geração da documentação.
class DocumentationGenerator {
    constructor(config: DocForgeConfig)
    // Métodos públicos
    async generate(): Promise&amp;lt;void&amp;gt;
    async processMarkdownFiles(): Promise&amp;lt;DocumentPage[]&amp;gt;
    generateNavigation(): NavigationItem[]
    async generatePages(): Promise&amp;lt;void&amp;gt;
    async copyAssets(): Promise&amp;lt;void&amp;gt;
    // Métodos de configuração
    setConfig(config: Partial&amp;lt;DocForgeConfig&amp;gt;): void
    getConfig(): DocForgeConfig
    // Eventos
    on(event: &amp;#39;start&amp;#39; | &amp;#39;progress&amp;#39; | &amp;#39;complete&amp;#39; | &amp;#39;error&amp;#39;, callback: Function): void
    off(event: string, callback: Function): void
}
Exemplo de uso:
import { DocumentationGenerator } from &amp;#39;@riligar/knowledge&amp;#39;
const generator = new DocumentationGenerator({
    inputDir: &amp;#39;./docs&amp;#39;,
    outputDir: &amp;#39;./dist&amp;#39;,
    site: {
        title: &amp;#39;Minha Documentação&amp;#39;,
        description: &amp;#39;Documentação do projeto&amp;#39;,
        baseUrl: &amp;#39;/&amp;#39;,
        author: &amp;#39;Autor&amp;#39;
    }
})
// Eventos
generator.on(&amp;#39;start&amp;#39;, () =&amp;gt; console.log(&amp;#39;Iniciando geração...&amp;#39;))
generator.on(&amp;#39;progress&amp;#39;, (progress) =&amp;gt; console.log())
generator.on(&amp;#39;complete&amp;#39;, () =&amp;gt; console.log(&amp;#39;Geração concluída!&amp;#39;))
generator.on(&amp;#39;error&amp;#39;, (error) =&amp;gt; console.error(&amp;#39;Erro:&amp;#39;, error))
// Gerar documentação
await generator.generate()
SearchIndexGenerator
Classe responsável pela geração do índice de busca.
class SearchIndexGenerator {
    constructor(config?: SearchConfig)
    // Métodos públicos
    addPage(page: DocumentPage): void
    addDocument(document: SearchDocument): void
    buildIndex(): lunr.Index
    getSerializableData(): SearchIndexData
    // Configuração
    setConfig(config: SearchConfig): void
    getConfig(): SearchConfig
    // Utilitários
    cleanContent(html: string): string
    generateExcerpt(content: string, maxLength?: number): string
}
Exemplo de uso:
import { SearchIndexGenerator } from &amp;#39;@riligar/knowledge&amp;#39;
const searchGenerator = new SearchIndexGenerator({
    indexFields: {
        title: { boost: 10 },
        excerpt: { boost: 5 },
        content: { boost: 1 }
    }
})
// Adicionar páginas
pages.forEach(page =&amp;gt; searchGenerator.addPage(page))
// Gerar índice
const index = searchGenerator.buildIndex()
const data = searchGenerator.getSerializableData()
// Salvar índice
await fs.writeFile(&amp;#39;search-index.json&amp;#39;, JSON.stringify(data))
DevServer
Servidor de desenvolvimento com live reload.
class DevServer {
    constructor(config: DocForgeConfig)
    // Métodos públicos
    async start(): Promise&amp;lt;void&amp;gt;
    async stop(): Promise&amp;lt;void&amp;gt;
    async restart(): Promise&amp;lt;void&amp;gt;
    // Configuração
    setPort(port: number): void
    setHost(host: string): void
    // Middleware
    use(middleware: DevMiddleware): void
    // Eventos
    on(event: &amp;#39;start&amp;#39; | &amp;#39;stop&amp;#39; | &amp;#39;reload&amp;#39; | &amp;#39;error&amp;#39;, callback: Function): void
}
Exemplo de uso:
import { DevServer } from &amp;#39;@riligar/knowledge&amp;#39;
const server = new DevServer(config)
// Middleware customizado
server.use({
    path: &amp;#39;/api&amp;#39;,
    handler: (req, res, next) =&amp;gt; {
        // Lógica customizada
        next()
    }
})
// Eventos
server.on(&amp;#39;start&amp;#39;, (port) =&amp;gt; console.log())
server.on(&amp;#39;reload&amp;#39;, () =&amp;gt; console.log(&amp;#39;Página recarregada&amp;#39;))
// Iniciar servidor
await server.start()
📄 Interfaces de Dados
DocumentPage
Representa uma página de documentação processada.
interface DocumentPage {
    readonly path: string
    readonly title: string
    readonly content: string
    readonly frontmatter: Record&amp;lt;string, any&amp;gt;
    readonly relativePath: string
    readonly url: string
    readonly excerpt?: string
    readonly tags?: string[]
    readonly date?: Date
    readonly author?: string
    readonly category?: string
    readonly order?: number
}
SearchDocument
Representa um documento no índice de busca.
interface SearchDocument {
    readonly id: string
    readonly title: string
    readonly content: string
    readonly excerpt: string
    readonly url: string
    readonly tags?: string[]
    readonly category?: string
    readonly date?: string
}
SearchIndexData
Dados serializáveis do índice de busca.
interface SearchIndexData {
    documents: SearchDocument[]
    indexData: any // Dados serializados do Lunr.js
    metadata: {
        version: string
        generatedAt: string
        documentsCount: number
        indexSize: number
    }
}
🎨 Sistema de Temas
ThemeConfig
Configuração de tema.
interface ThemeConfig {
    name: string
    version: string
    author: string
    description: string
    // Caminhos
    layouts: string
    assets: string
    // Configurações
    colors?: ColorScheme
    typography?: Typography
    spacing?: Spacing
    // Customizações
    customCSS?: string[]
    customJS?: string[]
    // Herança
    extends?: string
}
interface ColorScheme {
    primary: string
    secondary: string
    accent: string
    background: string
    surface: string
    text: string
    textSecondary: string
    border: string
    // Modo escuro
    dark?: {
        primary: string
        secondary: string
        accent: string
        background: string
        surface: string
        text: string
        textSecondary: string
        border: string
    }
}
interface Typography {
    fontFamily: string
    headingFontFamily?: string
    fontSize: {
        xs: string
        sm: string
        base: string
        lg: string
        xl: string
        &amp;#39;2xl&amp;#39;: string
        &amp;#39;3xl&amp;#39;: string
        &amp;#39;4xl&amp;#39;: string
    }
    fontWeight: {
        light: number
        normal: number
        medium: number
        semibold: number
        bold: number
    }
    lineHeight: {
        tight: number
        normal: number
        relaxed: number
    }
}
interface Spacing {
    unit: string
    scale: number[]
    container: {
        maxWidth: string
        padding: string
    }
}
Template Variables
Variáveis disponíveis nos templates HTML.
interface TemplateVariables {
    // Site
    site: SiteConfig
    // Página atual
    page: DocumentPage
    // Navegação
    navigation: NavigationItem[]
    sidebar: NavigationItem[]
    breadcrumbs: BreadcrumbItem[]
    // Conteúdo
    content: string
    tableOfContents: TOCItem[]
    // Metadados
    currentYear: number
    buildDate: string
    version: string
    // Funcionalidades
    features: FeatureConfig
    // Tema
    theme: ThemeConfig
    // Utilitários
    utils: {
        formatDate: (date: Date) =&amp;gt; string
        slugify: (text: string) =&amp;gt; string
        excerpt: (text: string, length: number) =&amp;gt; string
    }
}
interface BreadcrumbItem {
    title: string
    url?: string
    active: boolean
}
interface TOCItem {
    title: string
    anchor: string
    level: number
    children?: TOCItem[]
}
🔌 Plugin System (Futuro)
Plugin Interface
interface Plugin {
    name: string
    version: string
    description: string
    author: string
    // Hooks do ciclo de vida
    hooks: {
        beforeBuild?: () =&amp;gt; void | Promise&amp;lt;void&amp;gt;
        afterBuild?: () =&amp;gt; void | Promise&amp;lt;void&amp;gt;
        beforePage?: (page: DocumentPage) =&amp;gt; DocumentPage | Promise&amp;lt;DocumentPage&amp;gt;
        afterPage?: (page: DocumentPage) =&amp;gt; DocumentPage | Promise&amp;lt;DocumentPage&amp;gt;
        processMarkdown?: (content: string) =&amp;gt; string | Promise&amp;lt;string&amp;gt;
        generateNavigation?: (items: NavigationItem[]) =&amp;gt; NavigationItem[]
        modifyConfig?: (config: DocForgeConfig) =&amp;gt; DocForgeConfig
    }
    // Configuração do plugin
    config?: Record&amp;lt;string, any&amp;gt;
    // Dependências
    dependencies?: string[]
    // Inicialização
    init?: (context: PluginContext) =&amp;gt; void | Promise&amp;lt;void&amp;gt;
    // Cleanup
    destroy?: () =&amp;gt; void | Promise&amp;lt;void&amp;gt;
}
interface PluginContext {
    config: DocForgeConfig
    generator: DocumentationGenerator
    logger: Logger
    utils: PluginUtils
}
interface PluginUtils {
    readFile: (path: string) =&amp;gt; Promise&amp;lt;string&amp;gt;
    writeFile: (path: string, content: string) =&amp;gt; Promise&amp;lt;void&amp;gt;
    copyFile: (src: string, dest: string) =&amp;gt; Promise&amp;lt;void&amp;gt;
    ensureDir: (path: string) =&amp;gt; Promise&amp;lt;void&amp;gt;
    glob: (pattern: string) =&amp;gt; Promise&amp;lt;string[]&amp;gt;
}
Plugin de Exemplo
// plugins/analytics-plugin.ts
export const analyticsPlugin: Plugin = {
    name: &amp;#39;analytics-plugin&amp;#39;,
    version: &amp;#39;1.0.0&amp;#39;,
    description: &amp;#39;Adiciona Google Analytics às páginas&amp;#39;,
    author: &amp;#39;RiliGar&amp;#39;,
    hooks: {
        afterPage: async (page) =&amp;gt; {
            if (this.config.googleAnalytics) {
                const analyticsScript = 
                page.content = page.content.replace(&amp;#39;&amp;lt;/head&amp;gt;&amp;#39;, )
            }
            return page
        }
    },
    config: {
        googleAnalytics: &amp;#39;&amp;#39;,
        trackingEvents: true
    }
}
🛠️ Utilitários
Logger
Sistema de logging integrado.
interface Logger {
    debug(message: string, context?: any): void
    info(message: string, context?: any): void
    warn(message: string, context?: any): void
    error(message: string, error?: Error): void
    // Configuração
    setLevel(level: &amp;#39;debug&amp;#39; | &amp;#39;info&amp;#39; | &amp;#39;warn&amp;#39; | &amp;#39;error&amp;#39;): void
    setFormat(format: &amp;#39;simple&amp;#39; | &amp;#39;json&amp;#39; | &amp;#39;pretty&amp;#39;): void
}
FileUtils
Utilitários para manipulação de arquivos.
interface FileUtils {
    readFile(path: string): Promise&amp;lt;string&amp;gt;
    writeFile(path: string, content: string): Promise&amp;lt;void&amp;gt;
    copyFile(src: string, dest: string): Promise&amp;lt;void&amp;gt;
    ensureDir(path: string): Promise&amp;lt;void&amp;gt;
    exists(path: string): Promise&amp;lt;boolean&amp;gt;
    glob(pattern: string, options?: GlobOptions): Promise&amp;lt;string[]&amp;gt;
    watch(pattern: string, callback: (event: string, path: string) =&amp;gt; void): FileWatcher
}
interface FileWatcher {
    close(): void
    add(path: string): void
    unwatch(path: string): void
}
MarkdownUtils
Utilitários para processamento de Markdown.
interface MarkdownUtils {
    parse(content: string): ParsedMarkdown
    render(content: string): string
    extractFrontmatter(content: string): FrontmatterResult
    generateTOC(content: string): TOCItem[]
    extractExcerpt(content: string, length?: number): string
    slugify(text: string): string
}
interface ParsedMarkdown {
    frontmatter: Record&amp;lt;string, any&amp;gt;
    content: string
    excerpt: string
    headings: HeadingItem[]
    links: LinkItem[]
    images: ImageItem[]
}
interface FrontmatterResult {
    frontmatter: Record&amp;lt;string, any&amp;gt;
    body: string
}
interface HeadingItem {
    level: number
    text: string
    anchor: string
}
interface LinkItem {
    text: string
    href: string
    title?: string
}
interface ImageItem {
    alt: string
    src: string
    title?: string
}
📊 Eventos e Hooks
Eventos do Sistema
type SystemEvent = 
    | &amp;#39;build:start&amp;#39;
    | &amp;#39;build:progress&amp;#39;
    | &amp;#39;build:complete&amp;#39;
    | &amp;#39;build:error&amp;#39;
    | &amp;#39;dev:start&amp;#39;
    | &amp;#39;dev:stop&amp;#39;
    | &amp;#39;dev:reload&amp;#39;
    | &amp;#39;file:change&amp;#39;
    | &amp;#39;file:add&amp;#39;
    | &amp;#39;file:remove&amp;#39;
interface EventEmitter {
    on(event: SystemEvent, callback: (...args: any[]) =&amp;gt; void): void
    off(event: SystemEvent, callback: (...args: any[]) =&amp;gt; void): void
    emit(event: SystemEvent, ...args: any[]): void
    once(event: SystemEvent, callback: (...args: any[]) =&amp;gt; void): void
}
Hooks de Processamento
interface ProcessingHooks {
    beforeMarkdownProcess: (content: string, page: DocumentPage) =&amp;gt; string | Promise&amp;lt;string&amp;gt;
    afterMarkdownProcess: (html: string, page: DocumentPage) =&amp;gt; string | Promise&amp;lt;string&amp;gt;
    beforePageGenerate: (page: DocumentPage) =&amp;gt; DocumentPage | Promise&amp;lt;DocumentPage&amp;gt;
    afterPageGenerate: (page: DocumentPage) =&amp;gt; DocumentPage | Promise&amp;lt;DocumentPage&amp;gt;
    beforeNavigationGenerate: (items: NavigationItem[]) =&amp;gt; NavigationItem[]
    afterNavigationGenerate: (items: NavigationItem[]) =&amp;gt; NavigationItem[]
    beforeSearchIndex: (documents: SearchDocument[]) =&amp;gt; SearchDocument[]
    afterSearchIndex: (index: SearchIndexData) =&amp;gt; SearchIndexData
}
🔧 CLI API
Comandos Programáticos
import { CLI } from &amp;#39;@riligar/knowledge&amp;#39;
const cli = new CLI()
// Build
await cli.build({
    config: &amp;#39;./custom.config.ts&amp;#39;,
    input: &amp;#39;./docs&amp;#39;,
    output: &amp;#39;./dist&amp;#39;,
    verbose: true
})
// Dev
await cli.dev({
    port: 3000,
    host: &amp;#39;localhost&amp;#39;,
    open: true
})
// Serve
await cli.serve({
    port: 8080,
    dir: &amp;#39;./dist&amp;#39;
})
// Init
await cli.init({
    dir: &amp;#39;./my-docs&amp;#39;,
    template: &amp;#39;default&amp;#39;
})
🎯 Exemplos Avançados
Configuração Completa
// docforge.config.ts
import type { DocForgeConfig } from &amp;#39;@riligar/knowledge&amp;#39;
export default {
    inputDir: &amp;#39;./docs&amp;#39;,
    outputDir: &amp;#39;./dist&amp;#39;,
    themesDir: &amp;#39;./themes&amp;#39;,
    site: {
        title: &amp;#39;Knowledge Base Avançada&amp;#39;,
        description: &amp;#39;Documentação técnica completa com todas as funcionalidades&amp;#39;,
        baseUrl: &amp;#39;/&amp;#39;,
        author: &amp;#39;Equipe de Desenvolvimento&amp;#39;,
        keywords: [&amp;#39;documentação&amp;#39;, &amp;#39;api&amp;#39;, &amp;#39;guias&amp;#39;, &amp;#39;tutoriais&amp;#39;],
        language: &amp;#39;pt-BR&amp;#39;,
